Rules.InvariantScript:
Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
UpdateContext({locConflict: false, locDecision: "", locRequiresReason: false});

// This screen is only meaningful with an exception id passed from the queue.
// Studio runs OnVisible whenever the screen is previewed, with no context
// variable set - calling the procedure with a null @ExceptionId then fails and,
// because gblError is global, the failure used to surface on EVERY screen.
If(
    IsBlank(locExceptionId),
    Clear(colActions);
    Clear(colHistory);
    Set(gblEx, Blank());
    // Both arms of If() must yield the same type. The other arm ends in an
    // IfError() wrapping ClearCollect(), which yields a Table, so each arm is
    // closed with the same Boolean statement - which is also the only place
    // the busy flag needs clearing.
    Set(gblBusy, false),

    IfError(
        Set(
            gblExDetail,
            db_dq_sandbox.dquspGetExceptionDetail({ActorUpn: gblActorUpn, ExceptionId: locExceptionId})
        ),
        Set(gblError, {IsVisible: true, Title: "Could not open the exception", Detail: FirstError.Message})
    );
    Set(gblEx, First(gblExDetail.ResultSets.Table1));

    // Table2 is the set of transitions available for THIS exception and THIS
    // actor, already filtered server-side for role and for IsSystemOnly.
    // RESOLVED_FIXED and CLOSED can therefore never appear here.
    ClearCollect(colActions, gblExDetail.ResultSets.Table2);

    IfError(
        ClearCollect(
            colHistory,
            Filter(
            db_dq_sandbox.dquspGetExceptionHistory({ActorUpn: gblActorUpn, ExceptionId: locExceptionId}).ResultSets.Table1,
                !IsBlank(HistoryId)
            )
        ),
        Set(gblError, {IsVisible: true, Title: "Could not load history", Detail: FirstError.Message})
    );
    Set(gblBusy, false)
)

Set(
    gblExDetail,
    db_dq_sandbox.dquspGetExceptionDetail({ActorUpn: gblActorUpn, ExceptionId: locExceptionId})
);
Set(gblEx, First(gblExDetail.ResultSets.Table1));
ClearCollect(colActions, gblExDetail.ResultSets.Table2);
ClearCollect(
    colHistory,
    Filter(
    db_dq_sandbox.dquspGetExceptionHistory({ActorUpn: gblActorUpn, ExceptionId: locExceptionId}).ResultSets.Table1,
        !IsBlank(HistoryId)
    )
)

Navigate(
    scrQueue,
    ScreenTransition.None,
    {
        locInAssignee: locBackAssignee,
        locInSeverity: locBackSeverity,
        locInOverdue: locBackOverdue,
        locInCluster: locBackCluster
    }
)

UpdateContext(
    {
        locDecision: LookUp(colActions, ActionCode = drpDecisionED.Selected.ActionCode, ToStatusCode),
        locRequiresReason: Coalesce(
            LookUp(colActions, ActionCode = drpDecisionED.Selected.ActionCode, RequiresReason),
            false
        )
    }
)

Set(gblBusy, true);
IfError(
    Set(
        gblWriteResult,
        First(
            db_dq_sandbox.dquspSetExceptionStatus(
                {
                    ActorUpn: gblActorUpn,
                    ExceptionId: gblEx.ExceptionId,
                    ToStatusCode: locDecision,
                    Comment: Trim(txtReasonED.Text),
                    RowVersion: gblEx.RowVersionCol
                }
            ).ResultSets.Table1
        )
    ),
    Set(gblError, {IsVisible: true, Title: "The decision was not saved", Detail: FirstError.Message})
);
// OPEN QUESTION 1a: the value domain of Outcome is not documented. These branches
// assume OK / CONFLICT / FORBIDDEN. Confirm against the procedure body and correct
// HERE — this is the only place the values are interpreted on this screen.
Switch(
    Upper(Coalesce(gblWriteResult.Outcome, "")),
    "OK",
    Notify("Decision recorded.", NotificationType.Success, 3000);
    Reset(txtReasonED);
    Select(btnDoReloadED),
    "CONFLICT",
    // Never retried silently: the user decided against information that has since
    // changed. Their typed reason is deliberately left in place.
    UpdateContext({locConflict: true});
    Select(btnDoReloadED),
    "FORBIDDEN",
    Notify("You do not have permission to do that. " & Coalesce(gblWriteResult.Message, ""), NotificationType.Error, 6000),
    Notify(
        Coalesce(gblWriteResult.Message, "Unexpected response from the platform. Nothing was saved."),
        NotificationType.Error,
        6000
    )
);
Set(gblBusy, false)

Set(gblBusy, true);
IfError(
    Set(
        gblWriteResult,
        First(
            db_dq_sandbox.dquspAddExceptionComment(
                {
                    ActorUpn: gblActorUpn,
                    ExceptionId: gblEx.ExceptionId,
                    Comment: Trim(txtCommentED.Text)
                }
            ).ResultSets.Table1
        )
    ),
    Set(gblError, {IsVisible: true, Title: "The comment was not saved", Detail: FirstError.Message})
);
If(
    Upper(Coalesce(gblWriteResult.Outcome, "")) = "OK",
    Reset(txtCommentED);
    Notify("Comment added.", NotificationType.Success, 3000),
    Notify(Coalesce(gblWriteResult.Message, "The comment was not saved."), NotificationType.Error, 6000)
);
Set(gblBusy, false);
Select(btnDoReloadED)
